values ('8f24e09c-692c-460a-98cb-ffd3b1e08ae7', 'c3c15fe0-93c8-415b-94fb-7af095e3709a', '1eee23eb-1406-4aa7-9218-6d647d743009', 'the-elephant-and-the-rider', 'The Elephant and the Rider', 'Meet the fast, emotional you and the slow, deliberate you, and learn who''s really driving.', 420, null, true, 0, '[{"atSeconds":0,"title":"The spark"},{"atSeconds":126,"title":"What the research says"},{"atSeconds":286,"title":"Make it yours"}]'::jsonb, array['System 1 is fast, automatic and emotional; System 2 is slow, effortful and logical.', 'Most daily decisions are made by System 1 and justified afterwards by System 2.', 'Change sticks when you direct the rider AND motivate the elephant.']::text[], 'Today, catch one decision you made in under a second. Write down what your ''elephant'' wanted and what your ''rider'' said about it afterwards.')
