values ('c3a7483f-a364-4579-b6ff-4808b52d5d1c', 'c3c15fe0-93c8-415b-94fb-7af095e3709a', '1eee23eb-1406-4aa7-9218-6d647d743009', 'your-brain-is-a-prediction-machine', 'Your Brain Is a Prediction Machine', 'You don''t see the world as it is, you see what your brain expects. Here''s how to use that.', 480, null, false, 1, '[{"atSeconds":0,"title":"The spark"},{"atSeconds":144,"title":"What the research says"},{"atSeconds":326,"title":"Make it yours"}]'::jsonb, array['Perception is a controlled hallucination: the brain predicts, then checks.', 'Expectations literally change experience (placebo, pain, taste).', 'Updating predictions is the essence of learning about yourself.']::text[], 'Pick one recurring situation you dread. Write your prediction for it, then after it happens, grade how accurate it was.')
