values ('a7283a7a-f6e6-49ef-a716-4a21d8b9f221', 'the-persuasion-lab', 'The Persuasion Lab', 'The ethical science of influence, how to be heard, trusted and followed.', 'Influence isn''t manipulation when it helps people make choices they''ll thank you for. In The Persuasion Lab you''ll run live experiments on yourself and others using the principles of reciprocity, social proof, framing and narrative, and learn to spot when they''re being used on you.', 'Influence', 'Intermediate', 9900, 'usd', null, 'iris', '◆', '{"name":"Theo Lindqvist","title":"Behavioral Scientist","bio":"Theo designs habit and decision systems for health start-ups and teaches behavioral economics without the jargon."}'::jsonb, array['Apply the seven principles of influence ethically at work and home', 'Frame requests so people want to say yes', 'Recognise and defuse manipulation tactics used on you']::text[], true, true, 2)
