insert into public.courses (id, slug, title, subtitle, description, category, level, price_cents, currency, stripe_price_id, theme, glyph, instructor, outcomes, published, featured, position)
values ('508429d6-3eb1-42bf-bb21-847a4f2afbd5', 'habit-architecture', 'Habit Architecture', 'Design your environment so the right behaviour becomes the easy behaviour.', 'Willpower is a terrible strategy. Habit Architecture teaches you to engineer cues, friction and identity so good habits run on autopilot and bad ones quietly starve. You''ll leave with a working habit system you designed yourself, tested live inside the lessons.', 'Habits', 'Beginner', 6900, 'usd', null, 'tide', '▲', '{"name":"Theo Lindqvist","title":"Behavioral Scientist","bio":"Theo designs habit and decision systems for health start-ups and teaches behavioral economics without the jargon."}'::jsonb, array['Map the cue-routine-reward loops behind your current habits', 'Use friction and defaults to make change effortless', 'Build identity-based habits that survive bad weeks']::text[], true, false, 3)
