values ('140cbb1a-8120-4bf0-9368-90c178987dfd', 'attachment-and-you', 'Attachment & You', 'Understand the invisible blueprint behind how you love, trust and connect.', 'Why do some people text back instantly while you spiral? Why do you pull away when things get close? Attachment & You explores the science of attachment styles, helps you identify your own patterns, and gives you practical ways to build more secure relationships, romantic, platonic and professional.', 'Relationships', 'Intermediate', 8900, 'usd', null, 'blush', '❦', '{"name":"Noor Haddad, MA","title":"Relationship & Attachment Researcher","bio":"Noor studies how early bonds shape adult love, friendship and work, and how people rewrite those patterns."}'::jsonb, array['Identify your attachment tendencies and their triggers', 'Communicate needs clearly without protest behaviours', 'Practise earned security with small, repeatable actions']::text[], true, false, 4)
