values ('815499ea-9e1a-40ca-ad48-2f82fe6274d0', 'shadow-work', 'Shadow Work & Self-Sabotage', 'Meet the parts of you that hold you back, and turn them into allies.', 'Procrastination, perfectionism, impostor feelings: they''re not flaws, they''re protectors with outdated instructions. Blending Jungian shadow work with modern research on self-sabotage and the inner critic, this course helps you understand why you get in your own way, and how to stop.', 'Self-Knowledge', 'Advanced', 8900, 'usd', null, 'iris', '☾', '{"name":"Dr. Amara Okafor","title":"Clinical Psychologist","bio":"Amara spent twelve years in private practice translating CBT and ACT research into tools people actually use on a Tuesday afternoon."}'::jsonb, array['Recognise projection and use your triggers as mirrors', 'Understand the protective purpose behind self-sabotage', 'Transform your inner critic into an inner coach']::text[], true, false, 6)
