values ('e7b8be0b-f3aa-492a-acd4-10d6ea1d9cb6', '815499ea-9e1a-40ca-ad48-2f82fe6274d0', '3be3ed5f-327c-4c5c-87e1-8de77537cb59', 'why-you-procrastinate', 'Why You Procrastinate', 'Procrastination is an emotion-regulation problem, not a time-management one.', 540, null, false, 2, '[{"atSeconds":0,"title":"The spark"},{"atSeconds":162,"title":"What the research says"},{"atSeconds":367,"title":"Make it yours"}]'::jsonb, array['We delay to escape negative feelings about a task.', 'Self-forgiveness for past procrastination reduces future procrastination.', 'Start with the ''next visible action'' to shrink the feeling.']::text[], 'Pick a task you''ve avoided. Name the feeling it triggers. Do only the next visible action for five minutes.')
